  /**
   * <!-- begin-user-doc -->
   * <!-- end-user-doc -->
   * <!-- begin-model-doc -->
   * Summary: Places the next pipe from the pipe queue onto the map at the given player-facing row and column.
   * Algorithm:
   *   1. Compute the internal column index: colIndex = col - 'A' + 1.
   *   2. Peek the head pipe from pipeQueue (do not consume yet).
   *   3. Call map.tryPlacePipe(row, colIndex, pipe) to attempt the placement.
   *   4. If the placement succeeds:
   *      a. Push the newly created FillableCell onto cellStack.
   *      b. Call pipeQueue.consume() to remove the head pipe.
   *      c. Increment numOfSteps.
   *      d. Return true.
   *   5. If the placement fails (out of range / not FillableCell / already occupied), return false and leave
   *      the queue and step count unchanged.
   * Related Features: numOfSteps, cellStack, map, pipeQueue
   * Related Classes: Map, PipeQueue, CellStack, FillableCell, Pipe
   * Input:
   *   row - int, the player-facing row index in [1..rows-2] (no row offset is applied).
   *   col - char, the player-facing column letter (e.g. 'A'); the internal index is col - 'A' + 1,
   *         which must lie in [1..cols-2].
   * Output: boolean - true if the pipe was placed, false otherwise.
   * Pre-condition:
   *   - pipeQueue must contain at least one pipe.
   *   - The cell at cells[row][colIndex] must be a FillableCell inside the playable area and must not be
   *     currently occupied.
   * Post-condition:
   *   - On success: cells[row][colIndex] holds the new pipe, the cell is recorded on top of cellStack,
   *     the pipe is removed from pipeQueue, and numOfSteps is incremented by 1.
   *   - On failure: the map, cellStack, pipeQueue, and numOfSteps are unchanged.
   * <!-- end-model-doc -->
   * @model annotation="http://www.ustb.edu.cn/sei/mde/EnhancedCodeGen generated='true'"
   * @generated NOT
   */
  public boolean placePipe(final int row, final char col)
  {
    final int colIndex = col - 'A' + 1;
    final Pipe pipe = getPipeQueue().peek();
    final boolean placed = getMap().tryPlacePipe(row, colIndex, pipe);
    if (placed)
    {
      final FillableCell placedCell = (FillableCell) getMap().getCell()[row][colIndex];
      getCellStack().push(placedCell);
      getPipeQueue().consume();
      setNumOfSteps(getNumOfSteps() + 1);
      return true;
    }
    return false;
  }

